  "usage_notes": [
    {
      "chord_quality": "min7",
      "function_role": "ii-chord-in-ii-v7-i",
      "narrative": "Fisher prescribes voicing the ii chord (e.g., Dmin9) as a rootless chord on each of the three string sets (6-5-4-3, 5-4-3-2, 4-3-2-1): 'Note that the roots have been omitted from both the Dmin9 and G9 voicings. This is to allow the use of more interesting chords.' The essential 3rd and 7th must be retained; root and 5th are expendable. Chapter 3, p.56.",
      "source_principle_ids": [
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:ii-v7-i-harmonic-framework:essential-tones-floor",
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:ii-v7-i-harmonic-framework:root-fifth-omission"
      ],
      "source_work_id": "jazz-guitar-method-vol-2-intermediate",
