      "granularity_name": "voicing-floor"
    },
    {
      "chord_quality": "min7",
      "function_role": "ii-chord-lick-target",
      "narrative": "Fisher prescribes learning sample licks over minor chords, transposing them to all twelve keys, and inserting them into solos immediately: 'Here are some sample licks to use over minor chords. Once again, learn, transpose and insert these into your solos as soon as possible!' Begin each lick phrase on a chord tone, preferring 3rds and 7ths as target notes. Chapter 4, p.64.",
      "source_principle_ids": [
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:lick-vocabulary-system:learn-transpose-apply",
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:ii-v7-i-harmonic-framework:target-note-melodic-motion"
      ],
      "source_work_id": "jazz-guitar-method-vol-2-intermediate",
      "references": [
        {
