          "citation": "chapter 3 p.53-55"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "i",
      "granularity_name": "other"
    },
    {
      "chord_quality": "dom7",
      "function_role": "v7-lick-vocabulary-unaltered",
      "narrative": "Fisher prescribes learning dominant licks over unaltered V7 chords and extending their application to 9th, 11th, and 13th voicings: 'Here are some licks that will work well over unaltered dominant chords. Try using them over dominant 9th, 11th and 13th chords as well. Transpose them and apply them to your solos.' The prescription demands immediate transposition to all twelve keys. Chapter 4, p.68.",
      "source_principle_ids": [
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:lick-vocabulary-system:learn-transpose-apply",
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:lick-vocabulary-system:lick-extension-transfer"
