      "granularity_level": "i",
      "granularity_name": "other"
    },
    {
      "chord_quality": "dom7b5",
      "function_role": "altered-dominant-v7-variant",
      "narrative": "Fisher identifies the dom7b5 as 'an extremely important sound in jazz' built from the formula Root-3-b5-b7 (e.g., C-E-Gb-Bb in C). It is described as the familiar V7 chord with a lowered 5th. Fisher's substitution constraint applies: 'context is everything. Just because a substitution is theoretically correct doesn't mean it sounds good in every instance.' Chapter 2, p.18 and p.34.",
      "source_principle_ids": [
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:ii-v7-i-harmonic-framework:context-ear-substitution",
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:ii-v7-i-harmonic-framework:alteration-scope-rule"
      ],
      "source_work_id": "jazz-guitar-method-vol-2-intermediate",
