        },
        {
          "source": "jazz-guitar-method-vol-2-intermediate",
          "citation": "chapter 2 p.34"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "a",
      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "dom7b9",
      "function_role": "altered-dominant-rootless-symmetric",
      "narrative": "Fisher prescribes the rootless dom7b9 as a symmetric voicing that can be moved at minor-third intervals around the fingerboard without changing chord quality: 'when you drop the root, you can move the same fingering around the fingerboard at intervals of a minor 3rd without changing the chord's quality.' The formula is Root-3-5-b7-b9 (e.g., E-G#-B-D-F in E). Fisher establishes this minor-third symmetry as a practical fingerboard shortcut. Chapter 2, p.24.",
      "source_principle_ids": [
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:ii-v7-i-harmonic-framework:7b9-minor-third-symmetry",
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:ii-v7-i-harmonic-framework:root-fifth-omission"
      ],
      "source_work_id": "jazz-guitar-method-vol-2-intermediate",
