      "provenance": "extracted",
      "granularity_level": "b",
      "granularity_name": "voicing-floor"
    },
    {
      "chord_quality": "dom7#5",
      "function_role": "altered-dominant-v7-variant",
      "narrative": "Fisher identifies the dom7#5 as 'another very common sound in jazz' that is 'immediately recognizable,' built from the formula Root-3-#5-b7 (e.g., G-B-D#-F in G). It appears under multiple symbols including 7+, 7aug, and 7b13; adding the 9th yields 9#5 or 9+. Fisher's ear-and-context substitution constraint governs its deployment: theoretical correctness alone does not justify its use. Chapter 2, p.21 and p.34.",
      "source_principle_ids": [
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:ii-v7-i-harmonic-framework:context-ear-substitution",
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:ii-v7-i-harmonic-framework:alteration-scope-rule"
