      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "maj7",
      "function_role": "i-chord-tonic-resolution-target",
      "narrative": "Fisher prescribes the maj7 as the tonic resolution target of the ii-V7-I, with the major scale of the I chord governing diatonic improvisation: 'use the major scale of the I chord. If the progression is Gmin7-C7-FMaj7, improvise using the F Major scale.' The maj7 chord's 3rd and 7th must be retained in any voicing; root and 5th may be omitted. Chapter 1, p.8 and Chapter 2, p.17.",
      "source_principle_ids": [
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:ii-v7-i-harmonic-framework:diatonic-scale-rule-with-altered-exception",
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:ii-v7-i-harmonic-framework:essential-tones-floor"
      ],
      "source_work_id": "jazz-guitar-method-vol-2-intermediate",
