    },
    {
      "chord_quality": "maj7",
      "function_role": "i-chord-lick-vocabulary",
      "narrative": "Fisher prescribes learning eight sample licks over major-type chords, immediately transposing them to all twelve keys, and inserting them into real songs: 'These licks are labeled with major 7th chords but will work equally well with major 6th, major 9th and major 13th chords. Experiment and let your ear be your guide.' The lick family is explicitly extended to major 6th, 9th, and 13th voicings. Chapter 4, p.60.",
      "source_principle_ids": [
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:lick-vocabulary-system:learn-transpose-apply",
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:lick-vocabulary-system:lick-extension-transfer"
