      "granularity_name": "other"
    },
    {
      "chord_quality": "maj7",
      "function_role": "i-chord-altered-exception",
      "narrative": "Fisher proscribes applying the I-chord major scale rule when the maj7 (or any chord in the ii-V7-I) contains altered tones outside that scale: 'all chords with a raised or lowered 5th, 9th or 11th would make this rule inapplicable, because these altered tones are not diatonic.' When alteration is present, the player must find a scale that accommodates those altered tones rather than defaulting to the major scale. Chapter 1, p.8.",
      "source_principle_ids": [
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:ii-v7-i-harmonic-framework:diatonic-scale-rule-with-altered-exception"
      ],
      "source_work_id": "jazz-guitar-method-vol-2-intermediate",
