      "granularity_level": "d",
      "granularity_name": "color-tone-policy"
    },
    {
      "chord_quality": "dom7",
      "function_role": "v7-chord-context-substitution-constraint",
      "narrative": "Fisher proscribes applying any chord substitution -- including theoretically valid ones -- without testing it against musical context and ear: 'Remember that when enhancing or substituting chords, context is everything. Just because a substitution is theoretically correct doesn't mean it sounds good in every instance. Experimentation is the way we find out what works.' This applies specifically to all V7 substitution moves including 7b5, 7#5, 7b9, and diminished triad substitutions. Chapter 2, p.34.",
      "source_principle_ids": [
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:ii-v7-i-harmonic-framework:context-ear-substitution"
      ],
      "source_work_id": "jazz-guitar-method-vol-2-intermediate",
