          "citation": "chapter 2 p.34"
        }
      ],
      "provenance": "extracted",
      "polarity": "proscriptive",
      "granularity_level": "e",
      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "dom7",
      "function_role": "v7-alteration-scope-constraint",
      "narrative": "Fisher proscribes altering any chord degree other than the 5th, 9th, or 11th: 'the only notes that can be altered in any chord are the 5th, 9th and the 11th.' This boundary applies across all dominant variants (dom7b5, dom7#5, dom7b9) and governs what extensions are permissible in any ii-V7-I chord. Chapter 2, p.17.",
      "source_principle_ids": [
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:ii-v7-i-harmonic-framework:alteration-scope-rule"
      ],
      "source_work_id": "jazz-guitar-method-vol-2-intermediate",
