          "citation": "chapter 3 p.56"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "b",
      "granularity_name": "voicing-floor"
    },
    {
      "chord_quality": "maj7",
      "function_role": "b7-arpeggio-technique-over-v7",
      "narrative": "Fisher prescribes using the major 7th chord as a melodic device over dominant function, specifically playing a Maj7 arpeggio rooted on the b7 of the V7 chord to imply upper extensions (9th, 11th, 13th). The arpeggio need not begin on its own root: 'Notice that you don't have to start the major 7th arpeggio on the root of the Maj7 chord.' This is the primary technique for adding color to V7 lines. Chapter 3, p.49.",
      "source_principle_ids": [
        "jody-fisher:jazz-guitar-method-vol-2-intermediate:ii-v7-i-harmonic-framework:maj7-from-b7-arpeggio-over-v7"
